<script lang="ts">
 import {tick,untrack} from 'svelte';
 import SharedHeaven from '../digital/SharedHeaven.svelte';
 import SoulTile from '../digital/SoulTile.svelte';
 import DivineFavor from '../digital/DivineFavor.svelte';
 import GameCard from '../GameCard.svelte';
 import Rack from './Rack.svelte';
 import {angels,decrees,judgments} from '$lib/data/game';
 import {formation,inspectFormation} from '$lib/engine/formations';
 import {decree,allowance,total,tryCommand,type State,type Group,type Command,type OrganizingPower} from '$lib/engine/engine';
 import type {TileGroup,Soul,SoulSpec,Repair} from '$lib/tabletop/rearrangement';
 import {acceptsDraft,type LiveDraft} from '$lib/backend/live';
 let {state:gameState,uid,busy=false,send,liveDraft=null,publish,tableId}:{state:State;uid:string;busy?:boolean;send:(command:Command)=>Promise<void>;liveDraft?:LiveDraft|null;publish?:(groups:Group[],dragging:boolean,purgatory:string|null)=>void;tableId:string}=$props();
 let board=$state<SharedHeaven>(null!);let draft=$state<Group[]>([]),opening=$state<string[]|undefined>(),stage=$state<Group[]|undefined>(),power=$state<OrganizingPower|undefined>(),selected=$state<string[]>([]),rackOrder=$state<string[]>([]),target=$state(''),rank=$state(1),count=$state(1),giftOpen=$state(false),giftGroup=$state(''),giftTiles=$state<string[]>([]),communionTile=$state<string|undefined>(),showCard=$state(false),message=$state(''),fly=$state<{tile:Soul;from:DOMRect;to:DOMRect}|null>(null);
 const me=$derived(gameState.players.find(p=>p.id===uid)!);
 const active=$derived(gameState.players[gameState.turn]);
 const myTurn=$derived(active?.id===uid&&gameState.phase==='play');
 const editable=$derived(myTurn&&!busy);
 const currentDecree=$derived(decree(gameState));
 const card=$derived(gameState.round===3?judgments[gameState.judgment-1]:decrees[currentDecree-1]);
 const angel=$derived(angels.find(a=>a.id===me?.angel));
 const remote=$derived(!myTurn&&acceptsDraft(gameState,liveDraft)?liveDraft:null);
 const committedKey=$derived(`${gameState.turnNumber}/${gameState.phase}/${JSON.stringify(gameState.heaven)}`);
 let previousKey='';
 $effect(()=>{const key=committedKey;if(key!==previousKey)untrack(()=>{draft=JSON.parse(JSON.stringify(gameState.heaven));opening=undefined;power=undefined;stage=undefined;communionTile=undefined;selected=[];giftTiles=[];message='';previousKey=key;});});
 const initial=$derived((remote?.groups??gameState.heaven).map(toView));
 const boardKey=$derived(`${committedKey}/${remote?`${remote.session}/${remote.sequence}`:'committed'}`);
 $effect(()=>{const revision=gameState.revision;if(myTurn)untrack(()=>publish?.(draft,false,draftPurgatory()));});
 const onTable=$derived(new Set(draft.flatMap(g=>g.tiles)));
 const remaining=$derived(me?me.hand.filter(id=>!onTable.has(id)&&!(power?.kind==='penance'&&power.tile===id)):[]);
 const rackIds=$derived([...rackOrder.filter(id=>remaining.includes(id)),...remaining.filter(id=>!rackOrder.includes(id)),...(power?.kind==='forgive'&&!onTable.has(power.tile)&&!remaining.includes(power.tile)?[power.tile]:[]),...(power?.kind==='transfigure'?power.tiles.filter(id=>!remaining.includes(id)):[])]);
 const rackTiles=$derived(rackIds.map(id=>gameState.tiles[id]));
 const playableRack=$derived(rackTiles.filter(t=>power?.kind!=='transfigure'||!power.tiles.includes(t.id)));
 const organizing=$derived.by(()=>{const c:Command={type:'organize',groups:draft,turn:gameState.turnNumber,...(opening?{opening}:{}),...(power?{power}:{}),...(stage?{stage}:{}),...(communionTile?{communionTile}:{})};return {command:c,error:tryCommand(gameState,uid,c)};});
 const giftName=$derived(angel?.title??'Gift');
 const eligibleGroups=$derived(draft.filter(g=>g.zone===null||g.zone===uid));
 function toView(g:Group):TileGroup{return {...g,tiles:g.tiles.map(id=>gameState.tiles[id]).filter(Boolean)};}
 function fromView(g:TileGroup):Group{return {id:g.id,x:g.x,y:g.y,tiles:g.tiles.map(t=>t.id),zone:g.zone??null,...(g.slots?{slots:g.slots}:{}),...(g.jokerFaces?{jokerFaces:g.jokerFaces}:{})};}
 function allowed(g:TileGroup){return editable&&(g.zone==null||g.zone===uid)&&(me.opened||!!opening||g.tiles.every(t=>me.hand.includes(t.id)));}
 function draftPurgatory(){return power?.kind==='penance'?power.tile:me.purgatory&&!draft.some(g=>g.tiles.includes(me.purgatory!))?me.purgatory:null;}
 function changed(gs:TileGroup[],dragging:boolean){if(!myTurn)return;draft=gs.map(fromView);if(!me.opened&&!opening){const first=draft.find(g=>g.tiles.every(id=>me.hand.includes(id))&&formation(g.tiles.map(id=>gameState.tiles[id]),currentDecree));if(first)opening=[...first.tiles];}publish?.(draft,dragging,draftPurgatory());}
 function toggle(id:string){selected=selected.includes(id)?selected.filter(t=>t!==id):[...selected,id];}
 async function action(c:Command){await send(c);selected=[];giftOpen=false;}
 function add(tile:Soul,x:number,y:number){if(!editable)return false;if(power?.kind==='transfigure'&&power.tiles.includes(tile.id)){message='Keep the two retrieved souls in your hand.';return false;}return board.placeTile(tile,x,y);}
 function reorder(ids:string[]){rackOrder=ids;if(remaining.length===me.hand.length&&gameState.phase!=='lobby')void send({type:'rack',tiles:ids.filter(id=>me.hand.includes(id))});}
 async function animate(tile:Soul,from:DOMRect|undefined){await tick();const el=document.querySelector<HTMLElement>(`[data-tile-id="${tile.id}"]`);if(!from||!el)return;fly={tile,from,to:el.getBoundingClientRect()};await tick();document.querySelector('.flying-soul')?.animate([{transform:'translate(0,0)'},{transform:`translate(${fly.to.x-from.x}px,${fly.to.y-from.y}px)`}],{duration:420,easing:'cubic-bezier(.2,.7,.2,1)'}).finished.finally(()=>fly=null);}
 function suggestion(spec:SoulSpec,groupId:string,repair:Repair){const tile=playableRack.find(t=>t.rank===spec.rank&&t.color===spec.color)??playableRack.find(t=>t.rank==='joker');const group=draft.find(g=>g.id===groupId);if(!tile||!group||!editable)return;const from=document.querySelector<HTMLElement>(`[data-rack-tile="${tile.id}"]`)?.getBoundingClientRect();let at=group.tiles.length;
  for(let i=0;i<=group.tiles.length;i++){const ts=[...group.tiles.slice(0,i),tile.id,...group.tiles.slice(i)].map(id=>gameState.tiles[id]);if(formation(ts,currentDecree)){at=i;break;}const targetIndex=repair.completed.findIndex(t=>t.rank===spec.rank&&t.color===spec.color);if(i===Math.min(targetIndex,group.tiles.length))at=i;}
  if(board.addToGroup(tile,groupId,at))void animate(tile,from);
 }
 function playSelected(){if(!selected.length||!editable)return;const anchor=document.querySelector('.heaven-board')!.getBoundingClientRect();for(const [i,id]of selected.entries()){const tile=gameState.tiles[id];if(!rackIds.includes(id))continue;const from=document.querySelector<HTMLElement>(`[data-rack-tile="${id}"]`)?.getBoundingClientRect();if(add(tile,anchor.left+40+i*47,anchor.top+100))void animate(tile,from);}selected=[];}
 function cancelDraft(){draft=JSON.parse(JSON.stringify(gameState.heaven));opening=undefined;power=undefined;stage=undefined;communionTile=undefined;selected=[];giftTiles=[];boardReset++;publish?.(draft,false,draftPurgatory());}
 let boardReset=$state(0);
 function chooseGiftTile(id:string){giftTiles=giftTiles.includes(id)?giftTiles.filter(t=>t!==id):[...giftTiles,id];}
 function planGift(){if(!me.angel)return;stage=JSON.parse(JSON.stringify(draft));const kind=me.angel;
  if(kind==='zadkiel'||kind==='raphael'){if(giftTiles.length!==1){message='Choose one soul in Heaven.';return;}const id=giftTiles[0];if(board.removeTile(id))power={kind:kind==='zadkiel'?'forgive':'penance',tile:id};}
  else if(kind==='jophiel'){if(giftTiles.length!==2){message='Choose exactly two souls in Heaven.';return;}for(const id of giftTiles)board.removeTile(id);power={kind:'transfigure',tiles:[...giftTiles]};}
  else if(kind==='selaphiel'||kind==='barachiel'){if(!giftGroup){message='Choose a complete formation.';return;}if(board.shelter(giftGroup,uid))power={kind:'sanctuary',group:giftGroup};}
  giftOpen=false;
 }
 async function useBefore(){const returned=[...selected];cancelDraft();const map:Record<string,'judgment'|'dance'|'calling'|'banish'>={raguel:'judgment',haniel:'dance',gabriel:'calling',michael:'banish'};await action({type:'before',power:map[me.angel!],rank:Number(rank),target,tiles:returned,count:Number(count),turn:gameState.turnNumber});}
 const selectableHeaven=$derived(eligibleGroups.filter(g=>g.zone===null).flatMap(g=>g.tiles));
</script>
<div class="game-table">
 <section class="standings" aria-label="Players and Divine Favor">{#each gameState.players as p}<div class:active={active?.id===p.id} class:self={p.id===uid}><strong>{p.name}{p.bot?' ◇':''}</strong><DivineFavor value={p.favor}/><span>{p.hand.length} souls · {total(p)+(p.scores.length<gameState.round?p.credit:0)} points</span><small>{gameState.phase==='angels'&&!gameState.players.every(p=>p.angel)?(p.angel?'Angel chosen':'Choosing an Angel'):angels.find(a=>a.id===p.angel)?.name??''}{p.opened?' · Opened':''}</small></div>{/each}</section>
 {#if gameState.phase==='lobby'}<section class="choice-panel"><h1>Your table is gathering</h1><p>Invite friends using the table link. Start with three to five players.</p>{#if uid===gameState.owner}<button disabled={busy||gameState.players.length>=5} onclick={()=>action({type:'bot',id:`bot-${crypto.randomUUID().slice(0,8)}`,name:`Angel ${gameState.players.length+1}`})}>Add computer</button> <button class="primary" disabled={busy||gameState.players.length<3} onclick={()=>action({type:'start'})}>Deal Angels</button>{:else}<p>Waiting for the host to deal.</p>{/if}</section>
 {:else if gameState.phase==='angels'}<section class="choice-panel"><h1>Choose your Angel</h1><p>Your gift stays with you for all three rounds.</p>{#if !me.angel}<div class="angel-choice">{#each me.options as id}<button disabled={busy} onclick={()=>action({type:'angel',angel:id})}><GameCard card={angels.find(a=>a.id===id)!}/><span>Choose {angels.find(a=>a.id===id)?.name}</span></button>{/each}</div>{:else}<p>Waiting for everyone to choose.</p>{/if}</section>
 {:else}
 <div class="round-bar"><div><strong>Round {gameState.round} of 3</strong> · {gameState.bag.length} in the bag<br/><span>{active?.id===uid?'Your turn':`${active?.name}’s turn`}{remote?' · rearranging Heaven':''}</span></div><button class="decree-link" onclick={()=>showCard=!showCard}>{card?.name} <span>{showCard?'▴':'▾'}</span></button></div>
 {#if showCard&&card}<div class="rule-detail"><GameCard {card}/><div><h2>{card.name}</h2><p>{card.detailed}</p></div></div>{/if}
 {#if gameState.phase==='judgment'}<section class="choice-panel"><h2>{card?.name}</h2>{#if !me.ready}{#if gameState.judgment===2}<p>Secretly choose another player.</p><select bind:value={target}><option value="">Choose a player</option>{#each gameState.players.filter(p=>p.id!==uid)as p}<option value={p.id}>{p.name}</option>{/each}</select><button disabled={busy||!target} onclick={()=>action({type:'judgment-choice',target})}>Fix my choice</button>{:else}<p>Tap up to five numbered souls on your rack to set them aside.</p><button disabled={busy||selected.length>5} onclick={()=>action({type:'judgment-choice',tiles:selected})}>Commit {selected.length} souls</button>{/if}{:else}<p>Your choice is fixed. Waiting for the others.</p>{/if}</section>{/if}
 {#if gameState.phase==='dance'}<section class="choice-panel"><h2>Dance of Souls</h2>{#if !gameState.dance?.choices[uid]}<p>Choose {gameState.dance?.count} souls from your rack. Everyone’s choice is fixed before the pass.</p><button disabled={busy||selected.length!==gameState.dance?.count} onclick={()=>action({type:'dance-choice',tiles:selected,turn:gameState.turnNumber})}>Pass to the right</button>{:else}<p>Your souls are selected. Waiting for the others.</p>{/if}</section>{/if}
 <SharedHeaven bind:this={board} game initialGroups={initial} boardKey={`${boardKey}/${boardReset}`} readOnly={!editable} canTouch={allowed} onChange={changed} onSuggestion={suggestion} hand={playableRack} inspect={tiles=>inspectFormation(tiles,currentDecree)} zoneLabel={zone=>`${gameState.players.find(p=>p.id===zone)?.name} · Sanctuary`}/>
 <div class="special-areas">{#each gameState.players as p}{@const purgatory=remote&&p.id===remote.actor?remote.purgatory:p.id===uid&&power?.kind==='penance'?power.tile:p.purgatory&&!draft.some(g=>g.tiles.includes(p.purgatory!))?p.purgatory:null}{#if purgatory}<div class="purgatory"><span>{p.name} · Purgatory</span><button disabled={!editable||p.id!==uid||power?.kind==='penance'} aria-label="Rescue Purgatory into Heaven" onclick={()=>{const b=document.querySelector('.heaven-board')!.getBoundingClientRect();board.placeTile(gameState.tiles[purgatory],b.left+50,b.top+200);}}><SoulTile rank={gameState.tiles[purgatory].rank} color={gameState.tiles[purgatory].color} size={40}/></button></div>{/if}{/each}</div>
 {#if remote}<p class="live-caption" role="status">{active.name} is rearranging Heaven.</p>{/if}
 {#if gameState.phase==='inspect'&&gameState.inspection?.player===uid}<section class="choice-panel"><h2>Keep one soul</h2><div class="inspect-tiles">{#each gameState.inspection.tiles as id}<button disabled={busy} onclick={()=>action({type:'keep',tile:id,turn:gameState.turnNumber})}><SoulTile rank={gameState.tiles[id].rank} color={gameState.tiles[id].color} size={60}/></button>{/each}</div></section>{/if}
 {#if gameState.phase==='after-turn'&&active.id===uid}<section class="choice-panel"><p>Take an extra turn with Zeal?</p><button disabled={busy} onclick={()=>action({type:'continue',zeal:true,turn:gameState.turnNumber})}>Use Zeal</button><button disabled={busy} onclick={()=>action({type:'continue',turn:gameState.turnNumber})}>End turn</button></section>{/if}
 {#if myTurn}<div class="turn-controls"><button class="primary" disabled={busy||!!organizing.error} title={organizing.error??'Complete your Organize action'} onclick={()=>action(organizing.command)}>Finish organizing</button><button disabled={busy} onclick={()=>action({type:'draw',turn:gameState.turnNumber})}>Draw · inspect {allowance(gameState,uid)}</button><button disabled={busy} onclick={cancelDraft}>Restore Heaven</button><button disabled={busy||selected.length===0} onclick={playSelected}>Play selected</button>{#if angel&&!me.used&&!me.purgatory}<button disabled={busy||!!power} onclick={()=>giftOpen=!giftOpen}>{giftName}</button>{/if}<small>{organizing.error}</small></div>{/if}
 {#if giftOpen&&myTurn&&angel}<section class="gift-panel"><h2>{angel.name} · {giftName}</h2><p>{angel.detailed}</p>
  {#if ['zadkiel','raphael','jophiel'].includes(me.angel!)}<p>Choose {me.angel==='jophiel'?'two souls':'one soul'} in Heaven.</p><div class="gift-tiles">{#each selectableHeaven as id}<button class:chosen={giftTiles.includes(id)} onclick={()=>chooseGiftTile(id)}><SoulTile rank={gameState.tiles[id].rank} color={gameState.tiles[id].color} size={35}/></button>{/each}</div><button onclick={planGift}>Arrange this gift</button>
  {:else if ['selaphiel','barachiel'].includes(me.angel!)}<select bind:value={giftGroup}><option value="">Choose a formation</option>{#each eligibleGroups.filter(g=>formation(g.tiles.map(id=>gameState.tiles[id]),currentDecree)===(me.angel==='selaphiel'?'choir':'procession'))as g}<option value={g.id}>{g.tiles.map(id=>gameState.tiles[id].rank).join(' · ')}</option>{/each}</select><button onclick={planGift}>Move to Sanctuary</button>
  {:else if me.angel==='uriel'}<button disabled={busy||!gameState.bag.length} onclick={()=>action({type:'draw',foretell:true,turn:gameState.turnNumber})}>Foretell · inspect up to eight</button>
  {:else if me.angel==='jegudiel'}<p>Zeal becomes available after you finish your turn.</p>
  {:else if me.angel==='chamuel'}<select bind:value={target}><option value="">Choose an opponent</option>{#each gameState.players.filter(p=>p.id!==uid)as p}<option value={p.id}>{p.name}</option>{/each}</select><button disabled={busy||!target} onclick={()=>action({type:'communion',target,turn:gameState.turnNumber})}>Look at their entire hand</button>
  {:else}<label>Rank <input type="number" min="1" max="13" bind:value={rank}/></label><label>Player <select bind:value={target}><option value="">Choose a player</option>{#each gameState.players.filter(p=>p.id!==uid)as p}<option value={p.id}>{p.name}</option>{/each}</select></label>{#if me.angel==='haniel'}<label>Souls to pass <input type="number" min="1" max={Math.min(...gameState.players.map(p=>p.hand.length))} bind:value={count}/></label>{/if}{#if me.angel==='raguel'}<p>Select the souls to return on your rack.</p>{/if}<button disabled={busy} onclick={useBefore}>Use {giftName}</button>{/if}
 </section>{/if}
 {#if gameState.communion?.player===uid}<section class="gift-panel"><h2>Communion · choose a soul</h2><p>Choose from the entire hand. Deliver it together with at least one of your own, or return it.</p><div class="gift-tiles">{#each gameState.players.find(p=>p.id===gameState.communion!.target)!.hand as id}<button class:chosen={communionTile===id} disabled={!!communionTile} onclick={()=>{const b=document.querySelector('.heaven-board')!.getBoundingClientRect();if(board.placeTile(gameState.tiles[id],b.left+100,b.top+200))communionTile=id;}}><SoulTile rank={gameState.tiles[id].rank} color={gameState.tiles[id].color} size={40}/></button>{/each}</div><button onclick={()=>{if(communionTile)board.removeTile(communionTile);communionTile=undefined;}}>Return the soul</button></section>{/if}
 {#if me.sanctuary&&myTurn}<div class="sanctuary-controls">{#each draft.filter(g=>g.zone===uid)as g}<button onclick={()=>board.shelter(g.id,null)}>Release {g.tiles.map(id=>gameState.tiles[id].rank).join(' · ')} from Sanctuary</button>{/each}{#each draft.filter(g=>g.zone===null&&formation(g.tiles.map(id=>gameState.tiles[id]),currentDecree)===(me.angel==='selaphiel'?'choir':'procession'))as g}<button onclick={()=>board.shelter(g.id,uid)}>Shelter {g.tiles.map(id=>gameState.tiles[id].rank).join(' · ')}</button>{/each}</div>{/if}
 {#if message}<p role="status">{message}</p>{/if}
 {#if gameState.phase==='round-end'||gameState.phase==='ended'}<section class="choice-panel result"><h1>{gameState.players.find(p=>p.id===gameState.winner)?.name} wins round {gameState.round}</h1>{#if gameState.lastResult?.stalemate}<p>The bag is empty and Heaven has settled.</p>{/if}<table><thead><tr><th>Angel</th>{#each [1,2,3]as n}<th>Round {n}</th>{/each}<th>Total</th></tr></thead><tbody>{#each [...gameState.players].sort((a,b)=>total(b)-total(a))as p}<tr><th>{p.name}</th>{#each [0,1,2]as n}<td>{p.scores[n]??'—'}</td>{/each}<td><strong>{total(p)}</strong></td></tr>{/each}</tbody></table>{#if gameState.phase==='ended'}<h2>{gameState.players.filter(p=>total(p)===Math.max(...gameState.players.map(total))).map(p=>p.name).join(' & ')} · God’s Favorite</h2>{:else if uid===gameState.owner}<button disabled={busy} onclick={()=>action({type:'next-round'})}>Deal round {gameState.round+1}</button>{:else}<p>Waiting for the host to deal the next round.</p>{/if}</section>{/if}
 <section class="your-hand"><div><strong>Your rack</strong><span>{rackTiles.length} souls{!me.opened?' · Meld a complete formation to open':''}</span></div><Rack tiles={rackTiles} canPlay={editable} committed={me.scales} {selected} onSelect={toggle} onDrop={add} onReorder={reorder}/></section>
 {/if}
</div>
{#if fly}<div class="flying-soul" style={`left:${fly.from.x}px;top:${fly.from.y}px`}><SoulTile rank={fly.tile.rank} color={fly.tile.color} size={44}/></div>{/if}
<style>
 .game-table{max-width:1600px;margin:auto}.standings{display:flex;gap:8px;flex-wrap:wrap;margin:14px 0}.standings>div{display:grid;grid-template-columns:64px 1fr;gap:1px 8px;min-width:160px;flex:1;border:1px solid #cbbd98;border-radius:10px;padding:8px 12px;background:#f6efdccc}.standings>div.active{border:2px solid #a8802b;box-shadow:0 0 14px #b7954433}.standings strong,.standings span,.standings small{grid-column:2}.standings :global(.divine-favor){--favor-size:64px;grid-row:1/4;grid-column:1}.standings small{font-size:12px}.standings .self strong:after{content:' · you';font-weight:400;font-size:12px}.round-bar{display:flex;justify-content:space-between;align-items:center;gap:16px;margin:12px 0}.round-bar strong{font-size:20px}.decree-link{max-width:55%;font-family:'Cormorant Garamond';font-size:22px}.choice-panel,.gift-panel{margin:16px 0;padding:24px;background:#faf3e2;border:1px solid #c6ab70;border-radius:12px}.choice-panel h1,.choice-panel h2,.gift-panel h2{margin:0 0 12px}.choice-panel p,.gift-panel p{max-width:75ch}.angel-choice{display:flex;gap:24px;justify-content:center;flex-wrap:wrap}.angel-choice>button{width:min(300px,42%);padding:0;border:0;background:none}.angel-choice>button>span{display:block;padding:12px}.angel-choice :global(.card){width:100%}.rule-detail{display:flex;align-items:center;gap:24px;margin:16px auto;max-width:800px}.rule-detail>:global(.card){width:220px;flex:none}.turn-controls{display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin:12px 0}.turn-controls small{flex-basis:100%;color:#745b33;font-size:13px}.turn-controls button{padding:10px 14px}.your-hand{position:sticky;bottom:0;background:#f5eddde8;backdrop-filter:blur(12px);padding:10px 0 6px;z-index:130}.your-hand>div{display:flex;justify-content:space-between;padding:0 10px 5px;font-size:13px}.your-hand strong{font-size:16px}.inspect-tiles,.gift-tiles{display:flex;flex-wrap:wrap;gap:7px;margin:12px 0}.inspect-tiles button,.gift-tiles button{padding:0;background:none;border:0;min-height:0;line-height:0}.gift-tiles button.chosen{outline:3px solid #b98b2f;transform:translateY(-4px)}.gift-panel label{display:inline-flex;align-items:center;gap:8px;margin:8px}.gift-panel input{width:70px}.special-areas{display:flex;gap:14px;flex-wrap:wrap}.purgatory{display:flex;gap:14px;align-items:center;padding:10px 18px;background:radial-gradient(#544e61,#302d41);color:#ffedc7;border:1px solid #baa275;border-radius:8px;margin-top:10px}.purgatory button{padding:0;background:none;border:0;min-height:0;line-height:0}.live-caption{font-size:13px;color:#74613d;margin:6px 0}.flying-soul{position:fixed;z-index:2000;pointer-events:none;filter:drop-shadow(0 8px 5px #0006)}.result table{width:100%;border-collapse:collapse}.result th,.result td{text-align:left;padding:10px;border-bottom:1px solid #d4bf8d}.sanctuary-controls{display:flex;gap:8px;flex-wrap:wrap;margin:10px 0}.sanctuary-controls button{font-size:12px}select,input{padding:9px;font:inherit;border:1px solid #b49d70;border-radius:5px;background:#fffbf0}button{touch-action:manipulation}button:disabled{opacity:.5}button.primary{background:#5a603e;color:#fff7e6}.game-table :global(.play-viewport){height:clamp(360px,57dvh,740px)}@media(max-width:600px){.standings>div{min-width:120px;padding:5px;grid-template-columns:48px 1fr;font-size:12px}.standings :global(.divine-favor){--favor-size:64px;width:48px!important}.standings small{font-size:10px}.choice-panel,.gift-panel{padding:16px}.turn-controls button{font-size:12px;padding:8px}.your-hand{position:relative}.decree-link{font-size:17px}.rule-detail{gap:12px}.rule-detail>:global(.card){width:130px}.rule-detail p{font-size:13px}}
</style>
